package org.beckenburg.editor;

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Actual indexed corner edits; UV island traversal never invents source connectivity. */
public final class EditorUvTransformTest {
    private static final String SQUARE="o panel\nv 0 0 0\nv 1 0 0\nv 0 1 0\nv 1 1 0\nvt 0 0\nvt 1 0\nvt 0 1\nvt 1 1\nvn 0 0 2\nf 1/1/1 2/2/1 3/3/1\nf 3/3/1 2/2/1 4/4/1\n";
    private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private static void near(double a,double b){check(Math.abs(a-b)<1e-12,"UV coordinate "+a+" != "+b);}
    private interface Action{void run()throws Exception;}
    private static void refuse(Action action)throws Exception{try{action.run();throw new AssertionError("Expected UV refusal");}catch(IllegalArgumentException|java.io.IOException expected){}}
    private static EditorTopologyProject project(String text,Path target)throws Exception{return EditorTopologyProject.fromMesh(EditorMeshPipeline.read("uv.obj",text.getBytes(StandardCharsets.UTF_8)),"f".repeat(64),target);}
    private static void authority(EditorTopologyProject.State before,EditorTopologyProject.State after){
        check(after.vertices().equals(before.vertices())&&after.materials().equals(before.materials()),"UV operation cannot alter native positions, IDs or original materials");
        for(int i=0;i<before.faces().size();i++){var a=before.faces().get(i);var b=after.faces().get(i);check(a.id()==b.id()&&a.part().equals(b.part())&&a.material().equals(b.material()),"Native face identity/part/material retained");var old=List.of(a.a(),a.b(),a.c());var next=List.of(b.a(),b.b(),b.c());for(int j=0;j<3;j++)check(old.get(j).vertex()==next.get(j).vertex()&&Objects.equals(old.get(j).normal(),next.get(j).normal()),"Shared source connectivity and raw hard-edge corner normals retained");}
    }
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("native-uv-transform-");try{
            var p=project(SQUARE,root.resolve("uv.btop"));var before=p.snapshot();var history=new EditorHistory<>(p,20);
            var face=p.previewUvTransform(0,false,EditorTopologyProject.UvTransform.MOVE,.25,.125,false);check(p.snapshot()==before&&!history.canUndo(),"UV preview cannot mutate authoritative state/history");authority(before,face.snapshot());check(face.snapshot().faces().get(1)==before.faces().get(1),"Face scope leaves neighboring seam corners exactly untouched");near(face.snapshot().faces().get(0).a().u(),.25);near(face.snapshot().faces().get(0).a().v(),.125);p.cancelPreview(face);refuse(()->p.applyPreview(face));check(p.snapshot()==before,"Cancel exact snapshot");
            var island=p.previewUvTransform(0,true,EditorTopologyProject.UvTransform.MOVE,.25,.125,false);check(island.description().contains("2 faces"),"Connected native UV island includes both triangles");history.execute(()->p.applyPreview(island));authority(before,p.snapshot());check(p.topology().uvSeams()==0,"Island move keeps authored edge UV continuity");near(p.snapshot().faces().get(1).a().u(),.25);near(p.snapshot().faces().get(1).a().v(),1.125);check(history.undo()&&p.snapshot().equals(before)&&history.redo()&&p.snapshot().equals(island.snapshot()),"One shared undo/redo restores exact UV/normal/material state");
            p.save();var fresh=EditorTopologyProject.open(p.documentPath());check(fresh.snapshot().equals(p.snapshot()),"UV changes persist through actual native save and fresh reopen");Path obj=root.resolve("uv.obj");p.exportObj(p.observe(),obj,null);EditorObjWriter.validate(p.snapshot(),Files.readAllBytes(obj));
            p.restore(before);var rotation=p.previewUvTransform(0,true,EditorTopologyProject.UvTransform.ROTATE,90,0,false);near(rotation.snapshot().faces().get(0).a().u(),1);near(rotation.snapshot().faces().get(0).a().v(),0);authority(before,rotation.snapshot());
            var mirror=p.previewUvTransform(0,true,EditorTopologyProject.UvTransform.SCALE,-1,2,true);near(mirror.snapshot().faces().get(0).b().u(),-1);near(mirror.snapshot().faces().get(0).c().v(),2);authority(before,mirror.snapshot());
            var stale=p.previewUvTransform(0,false,EditorTopologyProject.UvTransform.MOVE,.1,0,true);p.moveVertex(0,-.1,0,0);var changed=p.snapshot();refuse(()->p.applyPreview(stale));check(p.snapshot()==changed,"Stale UV preview cannot overwrite a native geometry edit");p.restore(before);
            long revision=p.revision();for(double bad:new double[]{0,Double.NaN,Double.POSITIVE_INFINITY,1000001})refuse(()->p.previewUvTransform(0,true,EditorTopologyProject.UvTransform.SCALE,bad,1,false));refuse(()->p.previewUvTransform(0,false,EditorTopologyProject.UvTransform.MOVE,0,0,false));refuse(()->p.previewUvTransform(0,false,EditorTopologyProject.UvTransform.SCALE,1,1,false));refuse(()->p.previewUvTransform(0,false,EditorTopologyProject.UvTransform.ROTATE,360,0,false));refuse(()->p.previewUvTransform(999,false,EditorTopologyProject.UvTransform.MOVE,.1,0,false));check(p.snapshot()==before&&p.revision()==revision,"Invalid/no-op commands preserve snapshot and epoch");
            String seam=SQUARE.replace("f 3/3/1 2/2/1 4/4/1","vt .25 1\nf 3/5/1 2/2/1 4/4/1");var separated=project(seam,root.resolve("seam.btop"));var limited=separated.previewUvTransform(0,true,EditorTopologyProject.UvTransform.MOVE,.1,0,false);check(limited.description().contains("1 faces")&&limited.snapshot().faces().get(1)==separated.snapshot().faces().get(1),"Island traversal stops at authored UV seams");
            var material=EditorMeshMaterial.fromPng("fixture",EditorMeshMaterialTest.png(),10497,10497,EditorMeshMaterial.Alpha.OPAQUE,EditorMeshMaterial.Origin.BOTTOM_LEFT);p.applyPreview(p.previewBindMaterial(0,material));var bound=p.snapshot();var blocked=p.previewUvTransform(0,true,EditorTopologyProject.UvTransform.MOVE,.1,0,false);check(blocked.description().contains("1 faces")&&blocked.snapshot().faces().get(1)==bound.faces().get(1),"Island traversal stops at material boundary despite continuous UVs");authority(bound,blocked.snapshot());p.applyPreview(blocked);Path bundle=root.resolve("uv.obj.zip");p.exportObj(p.observe(),bundle,null);EditorObjBundle.validate(p.snapshot(),Files.readAllBytes(bundle));
            String disconnected=SQUARE+"v 1 0 0\nv 0 1 0\nv 1 1 0\nf 6/3/1 5/2/1 7/4/1\n";var split=project(disconnected,root.resolve("split.btop"));var connected=split.previewUvTransform(0,true,EditorTopologyProject.UvTransform.MOVE,.1,0,false);check(connected.description().contains("2 faces")&&connected.snapshot().faces().get(2)==split.snapshot().faces().get(2),"Coincident independent source IDs never join a UV island");
            if(args.length>0){var vertices=new ArrayList<EditorTopologyProject.Vertex>();var faces=new ArrayList<EditorTopologyProject.Face>();for(int i=0;i<120000;i++){long id=i*3L;vertices.add(new EditorTopologyProject.Vertex(id,"many",i*2,0,0));vertices.add(new EditorTopologyProject.Vertex(id+1,"many",i*2+1,0,0));vertices.add(new EditorTopologyProject.Vertex(id+2,"many",i*2,1,0));faces.add(new EditorTopologyProject.Face(i,"many",new EditorTopologyProject.Corner(id,0,0),new EditorTopologyProject.Corner(id+1,1,0),new EditorTopologyProject.Corner(id+2,0,1)));}var state=split.snapshot();split.restore(new EditorTopologyProject.State(state.sceneId(),state.sourceFingerprint(),state.name(),0,vertices,faces));var maximum=split.previewUvTransform(119999,true,EditorTopologyProject.UvTransform.MOVE,.1,.2,false);check(maximum.snapshot().faces().size()==120000&&maximum.description().contains("1 faces"),"Maximum indexed UV traversal bounded and exact");System.out.println("PASS maximum UV island traversal120000 faces/360000 vertices under256MiB");}
            System.out.println("PASS native UV face/island moves, bounds/origin rotation and signed scale: seams/material boundaries/source IDs, exact previews/history/save/OBJ bundle, unchanged geometry/raw normals and stale/no-op guards");
        }finally{try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
    }
}
